export function initChatMedia(c,h){const {$,state,req,element,button,toast}=c;const form=$('chat-form'),file=element('input');file.type='file';file.accept='image/jpeg,image/png,image/webp,application/pdf';file.hidden=true;file.id='chat-file';form.append(file);const attach=button('＋',()=>file.click(),'chat-attach');attach.setAttribute('aria-label','إرفاق صورة أو ملف PDF');form.prepend(attach);const mic=button('●',record,'chat-mic');mic.id='chat-mic';mic.setAttribute('aria-label','تسجيل رسالة صوتية');form.append(mic);const notice=element('div',undefined,'recording-notice');notice.hidden=true;form.before(notice);let recorder,stream,timer,cancelled=false,recordRoom,recordGeneration=0;const urls=new Map();
 async function send(blob,name,room){const mime=blob.type.split(';')[0];if(blob.size>2097152)throw new Error('حد المرفق 2 ميجابايت.');const path=state.user.id+'/'+crypto.randomUUID();await req('/storage/v1/object/chat-media/'+path,{method:'POST',body:blob,raw:true,headers:{'Content-Type':mime}});try{await req('/rest/v1/rpc/media_send',{method:'POST',body:{payload:{...room,path,name}}});await h.refresh();}catch(e){await req('/storage/v1/object/chat-media',{method:'DELETE',body:{prefixes:[path]}}).catch(()=>{});throw e;}}
 async function image(f){if(f.size>20*1024*1024)throw new Error('حجم الصورة الأصلية يتجاوز 20 ميجابايت.');const bitmap=await createImageBitmap(f),canvas=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.8));if(!blob)throw new Error('تعذّر تجهيز الصورة.');return blob;}
 file.onchange=async()=>{const f=file.files[0];file.value='';if(!f)return;const room=h.room();attach.disabled=true;try{if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(f.type))throw new Error('اختر صورة أو PDF.');await send(f.type.startsWith('image/')?await image(f):f,f.name,room);}catch(e){toast(e.message);}finally{attach.disabled=false;}};
 async function record(){if(recorder?.state==='recording'){recorder.stop();return;}if(!navigator.mediaDevices?.getUserMedia||!globalThis.MediaRecorder)throw new Error('التسجيل الصوتي غير مدعوم في هذا المتصفح.');const generation=++recordGeneration;recordRoom=h.room();stream=await navigator.mediaDevices.getUserMedia({audio:true});if(generation!==recordGeneration){stream.getTracks().forEach(t=>t.stop());return;}const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime){stream.getTracks().forEach(t=>t.stop());throw new Error('صيغة التسجيل غير مدعومة.');}const chunks=[];cancelled=false;recorder=new MediaRecorder(stream,{mimeType:mime,audioBitsPerSecond:48000});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=async()=>{clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());mic.classList.remove('recording');mic.textContent='●';notice.hidden=true;if(cancelled)return;mic.disabled=true;try{await send(new Blob(chunks,{type:mime.split(';')[0]}),'رسالة صوتية',recordRoom);}catch(e){toast(e.message);}finally{mic.disabled=false;}};recorder.start();mic.classList.add('recording');mic.textContent='■';notice.replaceChildren(element('span','يجري التسجيل — اضغط ■ للإرسال. الحد 90 ثانية.'),button('إلغاء التسجيل',reset));notice.hidden=false;timer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop();},90000);}
 async function render(m,row){if(!m.attachment_path||m.deleted_at)return;const node=element('div',undefined,'chat-media');row.append(node);try{let cached=urls.get(m.attachment_path);if(!cached||cached.expires<Date.now()){const r=await req('/storage/v1/object/sign/chat-media/'+m.attachment_path.split('/').map(encodeURIComponent).join('/'),{method:'POST',body:{expiresIn:600}});cached={url:'https://dlkykiducjimwehfhxfq.supabase.co/storage/v1'+r.signedURL,expires:Date.now()+540000};urls.set(m.attachment_path,cached);}const type=m.attachment_type||'';if(type.startsWith('image/')){const a=element('a'),img=element('img');img.src=cached.url;img.alt=m.attachment_name||'صورة';img.loading='lazy';a.href=cached.url;a.target='_blank';a.rel='noopener';a.append(img);node.append(a);}else if(type.startsWith('audio/')){const audio=element('audio');audio.controls=true;audio.preload='none';audio.src=cached.url;node.append(audio);}else{const a=element('a','▣ '+(m.attachment_name||'ملف PDF'));a.href=cached.url;a.target='_blank';a.rel='noopener';node.append(a);}}catch{node.append(button('إعادة تحميل المرفق',()=>{node.remove();return render(m,row);}));}}
 function reset(){recordGeneration++;cancelled=true;clearTimeout(timer);if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());notice.hidden=true;}
 document.addEventListener('visibilitychange',()=>{if(document.hidden)reset();});return {render,reset};
}
